<?php declare(strict_types=1); require_once dirname(__DIR__).'/config.php';require_once dirname(__DIR__).'/lib/common.php';tp_admin_required();$pdo=tp_db();
$rows=$pdo->query("SELECT m.*,v.vessel_name,v.eta,v.customs_iopr_departure_port FROM tp_manifest_items m JOIN tp_vessels v ON v.id=m.vessel_id ORDER BY m.updated_at DESC LIMIT 200")->fetchAll(); ?>
<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>자동 화물탐색</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f6f8}.card{border:0;border-radius:18px}</style></head><body><div class="container py-4"><div class="d-flex justify-content-between align-items-center"><div><h2 class="fw-bold">MRN → MSN 자동 화물탐색</h2><p class="text-secondary">v1.9 · API024 Shanghai 후보를 API001로 자동 검증</p></div><a class="btn btn-outline-dark" href="index.php">관리자</a></div><div class="alert alert-info">API001이 실제 응답한 화물만 저장합니다. <b>TESLA 판정은 품명(prnm)에 TESLA가 포함된 경우만</b> 인정합니다. 알림톡은 기존 설정(PPURIO_ENABLED)을 그대로 따릅니다.</div><div class="card shadow-sm"><div class="card-body table-responsive"><table class="table align-middle"><thead><tr><th>선박</th><th>MRN/MSN</th><th>cargMtNo</th><th>품명</th><th>수량</th><th>총중량</th><th>적재항</th><th>통관</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="<?=$r['tesla_flag']?'table-success':''?>"><td><b><?=h($r['vessel_name'])?></b><div class="small text-secondary"><?=h($r['eta'])?></div></td><td><?=h($r['mrn'])?> / <b><?=h($r['msn'])?></b></td><td><?=h($r['cargo_no'])?></td><td><?=$r['tesla_flag']?'<span class="badge text-bg-danger">TESLA</span> ':''?><?=h($r['product_name'])?></td><td><?=h($r['package_count'])?> <?=h($r['package_unit'])?></td><td><?=h($r['total_weight'])?> <?=h($r['weight_unit'])?></td><td><?=h($r['loading_port'])?></td><td><?=h($r['progress_status'])?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="8" class="text-center text-secondary py-4">아직 자동 탐색으로 저장된 화물이 없습니다. upgrade_v1_9.sql 실행 후 cron/check.php를 1회 실행하세요.</td></tr><?php endif?></tbody></table></div></div></div></body></html>
